import { LOGO, MARK } from './brand-paths';

/**
 * Stance brand marks, inlined so they inherit `currentColor` and follow every theme.
 * Masters live in /brand/logo/svg; paths are generated by scripts/build-brand.mjs.
 */
export function StanceMark({ size = 26, title }: { size?: number; title?: string }) {
  return (
    <svg
      width={(size * 382) / 376}
      height={size}
      viewBox={MARK.viewBox}
      fill="currentColor"
      focusable="false"
      {...(title ? { role: 'img', 'aria-label': title } : { 'aria-hidden': true })}
    >
      {title && <title>{title}</title>}
      <path d={MARK.d} />
    </svg>
  );
}

export function StanceLogo({
  height = 24,
  title = 'Stance',
}: {
  height?: number;
  title?: string | null;
}) {
  return (
    <svg
      className="site-logo"
      width={(height * 1682) / 376}
      height={height}
      viewBox={LOGO.viewBox}
      fill="currentColor"
      focusable="false"
      {...(title ? { role: 'img', 'aria-label': title } : { 'aria-hidden': true })}
    >
      {title && <title>{title}</title>}
      <path d={LOGO.d} />
    </svg>
  );
}

/** Header/footer lockup. The link around it provides the accessible name. */
export function StanceWordmark({ height = 24 }: { height?: number }) {
  return (
    <span className="site-wordmark">
      <StanceLogo height={height} title={null} />
    </span>
  );
}
